# operators: arithmetic, shifts, comparisons, boolean chains, unary, power
a = 1 + 2 - 3 * 4 / 5 // 6 % 7
b = 2 ** 3 ** 2
c = -2 ** 2
d = 2 ** -1
e = ~x
f = +x
g = -x
h = not x
i = x < y <= z < w
j = x == y != z
k = x in y
l = x not in y
m = x is y
n = x is not y
o = x << 2 >> 1
p = x & y | z ^ w
q = x @ y
r = a and b or not c and d
s = x if y else z
t = (a or b) and (c or d)
u = 1 if x else 2 if y else 3
